class RecipientActivity(DeclaredFamily, affix='RecipientActivity'):
    """Acquired recipient availability; no assignment, start or retry authority."""

    def turn_started_by(self, updated_at_ms: int) -> bool:
        return False

    @abstractmethod
    def pending_notification(self, notification: MessageNotification, *, blocked_by_prior: bool) -> MessageNotification:
        ...

    def after_inbox_read(self, notification, source, reads, document, snapshot):
        return notification

    def displayed_recipient(self, notification, source, reads, document, snapshot):
        return reads.displayed_recipient(source.message, notification.recipient_identity, snapshot, document=document)

    def selected_response(self, notification: MessageNotification, updated_at_ms: int) -> MessageNotification:
        if not self.turn_started_by(updated_at_ms):
            return replace(notification, state='Paused', busy=False, priority=3, detail='A response was selected, but no matching active turn is running. Outcome is unconfirmed; do not automatically retry.')
        return notification

@dataclass(frozen=True)
class RecordedRecipientActivity(RecipientActivity):
    """Durable history supplies no current process, readiness or inbox check."""

    def pending_notification(self, notification: MessageNotification, *, blocked_by_prior: bool) -> MessageNotification:
        return notification

    def selected_response(self, notification: MessageNotification, updated_at_ms: int) -> MessageNotification:
        return replace(notification, state='Response selected', busy=False, priority=3, detail='The recorded assignment selected a response; completion is not recorded.')

    def displayed_recipient(self, notification, source, reads, document, snapshot):
        return reads.historical_displayed_recipient(source.message, notification.recipient_identity, snapshot, document=document)

def selected_response(self, notification: MessageNotification, updated_at_ms: int) -> MessageNotification:
    if not self.turn_started_by(updated_at_ms):
        return replace(notification, state='Paused', busy=False, priority=3, detail='A response was selected, but no matching active turn is running. Outcome is unconfirmed; do not automatically retry.')
    return notification

def observe_recipients(self, recipients: Iterable[FrozenRecipient], *, snapshot: RegistrySnapshot) -> Mapping[str, RecipientActivity]:
    """Acquire one bounded window's recipients from the original source snapshot."""
    from .bus_publication import stable_thread_lookup
    snapshot.require_unambiguous_ownership()
    observations: dict[str, RecipientActivity] = {recipient.recipient_lookup: UnavailableRecipientActivity() for recipient in recipients}
    for thread in snapshot.threads.values():
        lookup = stable_thread_lookup(thread.created_at)
        if lookup not in observations:
            continue
        observations[lookup] = thread.execution.observe_recipient(self, snapshot, thread)
    return observations

class EngagedAssignment(BoundAssignment):

    def wake_frame(self, source, obligation) -> tuple[str, str]:
        from .wake import derive_exact_reply_target
        if obligation is None:
            raise IdentityConflict('full wake frame requires the current response obligation')
        obligation.lifecycle.require_preparation()
        if (obligation.execution_id, obligation.exact_target) != (self.decision.execution_id, derive_exact_reply_target(source)):
            raise IdentityConflict('full wake frame requires the current response obligation')
        return (self.mode.full_expectation(), 'you owe a response: ' + json.dumps({'target': obligation.exact_target, 'source_seq': source.seq, 'execution_id': obligation.execution_id}, ensure_ascii=True, separators=(',', ':')))

    def require_engagement(self) -> Engagement:
        return self.decision

    def notification(self, recipient, *, observation, updated_at_ms=0, triage_inflight=False, blocked_by_prior=False):
        return observation.selected_response(super().notification(recipient, observation=observation), updated_at_ms)
    notification_state = 'Responding…'
    notification_detail = 'The agent chose to respond; work is in progress.'
    notification_priority = 1
    notification_busy = True
    engaged = True

    @classmethod
    def successors(cls):
        return (CompletedAssignment, DeferredAssignment, FailedAssignment)

@dataclass(frozen=True, slots=True)
class HistorySource:
    """An immutable bus/registry snapshot attached by the destination MessageBus."""
    root: str
    original_root: str
    wire_root_id: str
    bus_identity: tuple[int, int]
    size: int
    snapshot_bus_revision: tuple[int, int, int, int]
    snapshot_registry_revision: tuple[int, int, int, int]
    provenance: RegistryProvenance

    @property
    def key(self) -> str:
        return self.root

    def validate(self) -> None:
        root = Path(self.root)
        if file_revision(root / 'bus.jsonl') != self.snapshot_bus_revision or file_revision(root / 'registry.json') != self.snapshot_registry_revision:
            raise ValueError('Historical snapshot changed; restore it before browsing')

    def require_original(self, root: Path) -> None:
        """Admit an original typed acquisition before destination publication."""
        root = root.resolve()
        if self.root != str(root) or self.original_root != str(root):
            raise ValueError('Recorded provenance belongs to another original source')
        self.validate()
        log = WireLog(root / 'bus.jsonl')
        info = log.path.stat()
        if log.read_metadata_unlocked(required=True).root_id != self.wire_root_id or (info.st_dev, info.st_ino) != self.bus_identity or info.st_size != self.size:
            raise ValueError('Recorded provenance lost original wire custody')

    @classmethod
    def require(cls, archive: HistoryArchive, key: str) -> HistorySource:
        source = next((item for item in archive.sources() if item.key == key), None)
        if source is None:
            raise ValueError('Historical source detached; refresh history')
        source.validate()
        return source

    def notification_references(self, archive: HistoryArchive, references):
        """Borrow this attached namespace's frozen deliveries and durable receipts."""
        from functools import partial
        from .presentation import MessageNotification

        def require_selected():
            if self.require(archive, self.key) != self:
                raise ValueError('Historical source changed; refresh history')
        require_selected()
        root = Path(self.root)
        result = MessageNotification.read_references(WireLog(root / 'bus.jsonl'), references, partial(MessageNotification.recorded_delivery_window, root, self.provenance))
        require_selected()
        return result

def notification_references(self) -> tuple[MessageReference, ...]:
    """An archived row has no current recipient handling authority."""
    return ()

def acknowledge(self, archive: HistoryArchive, registry: Registration) -> None:
    """Acknowledge exactly painted retained membership in its own ledger."""
    from .read_ledger import ReadLedger
    viewer = registry.require(self.viewer)
    if viewer.incarnation != self.displayed.viewer_identity or viewer.role.executable:
        raise ValueError('Historical viewer changed; refresh history')
    if self.source not in archive.sources():
        raise ValueError('Historical source detached; refresh history')
    self.source.validate()
    ReadLedger(Path(self.source.root) / ReadLedger.filename).mark_displayed(self.viewer, self.displayed)

def notification_references(self) -> tuple[MessageReference, ...]:
    """This live original may read current handling through its exact source."""
    return (self.reference,)

def acknowledge(self, name: str, target: str | None=None) -> int:
    """Mark an inbox or one conversation delivered. Returns count acknowledged."""
    with _store_lock(self._wire_lock_path):
        return self.bus.mark_delivered(name, target)

@dataclass(frozen=True, slots=True)
class MessageNotification:
    """Read-only display of one recipient's durable assignment decision."""
    window_limit: ClassVar[int] = 120
    recipient_identity: FrozenRecipient
    state: str
    detail: str
    priority: int = 3
    busy: bool = False
    message: Message | None = None
    displayed_to: tuple[ThreadIncarnation, ...] = ()

    @property
    def recipient(self) -> str:
        return self.recipient_identity.canonical_thread

    @classmethod
    def window(cls, root: Path, registry: Registration, log: WireLog, messages: Sequence[Message]) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
        """Read one visible window's actual recipient outcomes; never schedule work.

        Display uses the coordinator's existing assignment decoder and lifecycle.
        A missing coordination store or absent row supplies no receipt. Errors remain
        visible to the caller instead of becoming false successful delivery.
        """
        if len(messages) > cls.window_limit:
            raise ValueError('Notification reads require a bounded visible message window')
        references = tuple((reference for message in messages for reference in message.notification_references()))
        sources = log.deliveries_for_references(references)
        projected = cls.delivery_window(root, registry, sources)
        return {(message.seq, message.message_id): projected.get((message.seq, message.message_id), ()) for message in messages}

    @classmethod
    def references(cls, root: Path, registry: Registration, log: WireLog, references: Sequence[MessageReference]) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
        """Borrow mounted references in the original bounded delivery windows."""
        return cls.read_references(log, references, partial(cls.delivery_window, root, registry))

    @classmethod
    def read_references(cls, log: WireLog, references: Sequence[MessageReference], project: Callable[[Sequence[CommittedDelivery]], dict[tuple[int, str], tuple[MessageNotification, ...]]]) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
        """Share bounded original delivery acquisition across live/recorded cuts."""
        result = {}
        for start in range(0, len(references), cls.window_limit):
            sources = log.deliveries_for_references(references[start:start + cls.window_limit])
            result.update(project(sources))
        return result

    @classmethod
    def delivery_window(cls, root: Path, registry: Registration, sources: Sequence[CommittedDelivery]):
        """Project the original frozen audience even before handling is recorded."""
        from .agent_activity import AgentActivity
        if not sources:
            return {}
        snapshot = registry.snapshot()
        observations = AgentActivity(root, registry).observe_recipients((recipient for source in sources for recipient in source.audience.recipients), snapshot=snapshot)
        return cls.project_delivery_window(root, snapshot, sources, observations)

    @classmethod
    def recorded_delivery_window(cls, root: Path, namespace: RegistryProvenance, sources: Sequence[CommittedDelivery]):
        from .agent_activity import RecordedRecipientActivity
        observations = {recipient.recipient_lookup: RecordedRecipientActivity() for source in sources for recipient in source.audience.recipients}
        return cls.project_delivery_window(root, namespace, sources, observations)

    @classmethod
    def project_delivery_window(cls, root: Path, snapshot: RegistryProvenance, sources: Sequence[CommittedDelivery], observations: Mapping[str, RecipientActivity]) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
        """Original assignment and read authorities own both display projections."""
        from .notification_assignment import NotificationAssignment
        if len(sources) > cls.window_limit:
            raise ValueError('Notification reads require a bounded visible message window')
        keys = {(source.message.seq, source.message.message_id) for source in sources}
        result: dict[tuple[int, str], list[MessageNotification]] = {key: [] for key in keys}
        if not keys:
            return {}
        placeholders = ','.join(('?' for _ in keys))
        rows = NotificationAssignment.select(root, f'w.wire_seq IN ({placeholders})', tuple((key[0] for key in keys)))
        reads = ReadLedger(root / ReadLedger.filename)
        document = reads.read()
        for source in sources:
            key = (source.message.seq, source.message.message_id)
            for outcome in NotificationAssignment.for_delivery(source, rows):
                observation = observations[outcome.recipient.recipient_lookup]
                notification = observation.after_inbox_read(outcome.project(observation), source, reads, document, snapshot)
                result[key].append(replace(notification, displayed_to=observation.displayed_recipient(notification, source, reads, document, snapshot)))
        return {key: tuple(rows) for key, rows in result.items()}

    @classmethod
    def recent(cls, root: Path, registry: Registration, log: WireLog, name: str, *, limit: int=5) -> tuple[MessageNotification, ...]:
        """Recent assigned messages, including channel work, for one agent view.

        Reads the original assignments and source messages. This is not a DM
        delivery or a read acknowledgement, and never schedules another turn.
        """
        if not 1 <= limit <= 20:
            raise ValueError('Recent notification limit must be between 1 and 20')
        owner = registry.require(name)
        from .transcript_receipts import AssignedTranscriptSource
        sources = AssignedTranscriptSource.for_thread(root, owner, log).rows(limit=limit)
        return cls.for_sources(root, registry, owner, sources)

    @classmethod
    def for_sources(cls, root: Path, registry: Registration, owner: Thread, sources: Sequence[CommittedDelivery]) -> tuple[MessageNotification, ...]:
        """Project outcomes from the caller's original certified source window."""
        from .bus_publication import stable_thread_lookup
        lookup = stable_thread_lookup(owner.created_at)
        projected = cls.delivery_window(root, registry, sources)
        return tuple((replace(notification, message=source.message) for source in sources for notification in projected[source.message.seq, source.message.message_id] if source.audience.sender_lookup == lookup or notification.recipient_identity.recipient_lookup == lookup))

@classmethod
def read_references(cls, log: WireLog, references: Sequence[MessageReference], project: Callable[[Sequence[CommittedDelivery]], dict[tuple[int, str], tuple[MessageNotification, ...]]]) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
    """Share bounded original delivery acquisition across live/recorded cuts."""
    result = {}
    for start in range(0, len(references), cls.window_limit):
        sources = log.deliveries_for_references(references[start:start + cls.window_limit])
        result.update(project(sources))
    return result

